// news-image-20261124 v3: writes the 24 November 2026 world-news front page.
// The image is embedded below as base64 PNG data (drawn in this session
// with the Pillow script gen.py: 46 verified stories, 12 vector scenes,
// per-story source + confidence tag on every story, THE DAY IN NUMBERS
// sidebar, masthead, UTC timeline, dotted world map, DATE CHECK box and
// footer). No network is used. Output is fully deterministic: the same
// bytes on every run.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const IMAGE_B64 =
  "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output";
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(IMAGE_B64, "base64"));
